// Both triggers end up here: the website form (fields by label) and a GoHighLevel
// workflow webhook (contact fields in a JSON body). Turn either into one clean lead.

// The business the replies are written for. Change these lines for a client.
const BUSINESS = 'Northside Heating & Plumbing, a home services company in Columbus, Ohio: AC and furnace repair and replacement, water heaters, drain cleaning, general plumbing, same-day emergency calls';
const SIGN_OFF = 'Northside Heating & Plumbing';

return $input.all().map((item) => {
  const fromWebhook = item.json.body !== undefined;
  const src = fromWebhook ? item.json.body : item.json;
  const pick = (...keys) => {
    for (const key of keys) {
      const value = src[key];
      if (value !== undefined && value !== null && String(value).trim() !== '') {
        return String(value).trim();
      }
    }
    return '';
  };
  const name = pick('Name', 'name', 'full_name') ||
    [pick('first_name', 'firstName'), pick('last_name', 'lastName')].filter(Boolean).join(' ');

  return {
    json: {
      name,
      email: pick('Email', 'email').toLowerCase(),
      phone: pick('Phone', 'phone'),
      area: pick('Address or area', 'address', 'address1', 'city'),
      message: pick('What do you need?', 'message', 'Message', 'notes').slice(0, 4000),
      source: fromWebhook ? (pick('source').slice(0, 40) || 'GHL workflow') : 'website form',
      ghl_contact_id: fromWebhook ? pick('contact_id', 'contactId') : '',
      received_at: new Date().toISOString(),
      business: BUSINESS,
      sign_off: SIGN_OFF,
    },
  };
});

