{
  "type": "object",
  "properties": {
    "category": {
      "type": "string",
      "enum": ["hot", "warm", "cold", "spam"],
      "description": "hot = needs a service we offer now or soon (broken equipment, leak, no heat or cooling, a firm date). warm = real need but planning or no rush (replacement next season, comparing options). cold = only asking prices or general questions. spam = selling something to us, mass mailing, or unrelated."
    },
    "service": {
      "type": "string",
      "description": "Which of the business's services fits best, in 2 to 4 lowercase words (for example 'ac repair', 'water heater', 'drain cleaning'). 'other' if none fits."
    },
    "urgency": {
      "type": "string",
      "enum": ["high", "normal", "low"],
      "description": "high only if they say today, tomorrow, a deadline, no heat or cooling, an active leak, or a safety risk."
    },
    "summary": {
      "type": "string",
      "description": "One sentence, at most 25 words: who they are and what they need. Facts from the message only."
    },
    "reason": {
      "type": "string",
      "description": "At most 20 words: the facts from the message that decided the category."
    },
    "reply_draft": {
      "type": "string",
      "description": "Text or email reply for a person to review before sending. Required for hot, warm and cold leads. Empty string only for spam."
    }
  },
  "required": ["category", "service", "urgency", "summary", "reason", "reply_draft"]
}

