// Join the lead with what the AI decided, guard against odd output,
// and prepare everything GoHighLevel needs: tags, stage, note and task text.
const LOCATION_ID = '__GHL_LOCATION_ID__';
const PIPELINE_ID = '__GHL_PIPELINE_ID__';
const STAGE = {
  hot: '__GHL_STAGE_ID:hot__',
  warm: '__GHL_STAGE_ID:warm__',
  cold: '__GHL_STAGE_ID:cold__',
  spam: '__GHL_STAGE_ID:spam__',
};
const NEXT_STEP = {
  hot: 'Call today',
  warm: 'Reply today with questions',
  cold: 'Send short info reply',
  spam: 'Ignore',
};

return $input.all().map((item, index) => {
  const lead = $('Clean up the lead').itemMatching(index).json;
  const ai = item.json.output || {};
  const category = NEXT_STEP[ai.category] ? ai.category : 'warm';
  const urgency = ['high', 'normal', 'low'].includes(ai.urgency) ? ai.urgency : 'normal';
  const service = String(ai.service || 'other').toLowerCase().slice(0, 40);
  const reply = category === 'spam' ? '' : String(ai.reply_draft || '').trim();
  const nextStep = category !== 'spam' && !reply
    ? NEXT_STEP[category] + ' (no AI draft, write the reply by hand)'
    : NEXT_STEP[category];

  const parts = lead.name.split(/\s+/).filter(Boolean);
  const firstName = parts[0] || '';
  const lastName = parts.slice(1).join(' ');
  const tags = ['ai-' + category, 'speed-to-lead'];
  if (urgency === 'high') tags.push('urgent');
  if (service && service !== 'other') tags.push(service.replace(/[^a-z0-9 ]/g, '').trim().replace(/ +/g, '-'));

  const note = [
    'AI lead check (' + category.toUpperCase() + ', urgency ' + urgency + ')',
    'Summary: ' + (ai.summary || ''),
    'Why: ' + (ai.reason || ''),
    'Service: ' + service,
    'Next step: ' + nextStep,
    '',
    'Their message:',
    lead.message,
    '',
    reply ? 'Reply draft (check before sending):\n' + reply : 'No reply: marked as spam.',
  ].join('\n');

  return {
    json: {
      received_at: lead.received_at,
      source: lead.source,
      name: lead.name,
      first_name: firstName,
      last_name: lastName,
      email: lead.email,
      phone: lead.phone,
      area: lead.area,
      message: lead.message,
      category,
      urgency,
      service,
      summary: ai.summary || '',
      reason: ai.reason || '',
      reply_draft: reply,
      next_step: nextStep,
      tags,
      note,
      location_id: LOCATION_ID,
      pipeline_id: PIPELINE_ID,
      stage_id: STAGE[category],
      opportunity_name: (lead.name || 'New lead') + ' - ' + service,
      task_title: 'Call ' + (firstName || 'new lead') + ' now: ' + service,
      task_due: new Date(Date.now() + 60 * 60 * 1000).toISOString(),
    },
  };
});
